compile.workshop:
settings
{
	main
	{
		Mode Name: "https://workshop.codes/5AWEW"
		Description: "Proof of concept for client -> server data transfer. Upon pressing your interact key, you will be switched to a different hero depending on what key interact is bound to."
	}
	modes
	{
		Skirmish
		{
			enabled maps
			{
				Workshop Island
			}
		}
		General
		{
			Hero Limit: Off
			Respawn Time Scalar: 30%
		}
	}
}

variables {
    global:
        0: horizontalAngle1
        1: horizontalAngle2
    player:
        0: oldFacing
}

rule ("print stuff") {
    event {
        Ongoing - Global;
    }
    actions {
        Create HUD Text(All Players(All Teams), Custom String("interact = F -> bastion, U -> reinhardt, O -> ana"), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Create HUD Text(All Players(All Teams), Custom String("server side horizontal angles: {0}, {1}", Global.horizontalAngle1, Global.horizontalAngle2), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
    }
}

rule ("init host") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is Dummy Bot(Event Player) == False;
        Has Spawned(Event Player) == True;
    }
    actions {
        While(True);
            "Both of these have different precisions for some reason. But both are not accurate enough (or start facing is not accurate enough)."
            Set Global Variable(horizontalAngle1, Multiply(Horizontal Facing Angle Of(Event Player), 100));
            Set Global Variable(horizontalAngle2, Multiply(Horizontal Angle From Direction(Facing Direction Of(Event Player)), 100));
            Wait(0.016, Ignore Condition);
        End;
    }
}

rule ("press f") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is Button Held(Event Player, Button(Interact)) == True;
    }
    actions {
        Set Player Variable(Event Player, oldFacing, Facing Direction Of(Event Player));
        Start Facing(Event Player, If-Then-Else(Compare(Input Binding String(Button(Interact)), ==, Custom String("F")), Direction From Angles(30, 0), If-Then-Else(Compare(Input Binding String(Button(Interact)), ==, Custom String("U")), Direction From Angles(60, 0), If-Then-Else(Compare(Input Binding String(Button(Interact)), ==, Custom String("O")), Direction From Angles(90, 0), Direction From Angles(120, 0)))), 999999, To World, Direction and Turn Rate);
        "Because of precision errors, we round to the hundredth."
        Wait Until(Array Contains(Array(30, 60, 90), Divide(Round To Integer(Multiply(Horizontal Facing Angle Of(Event Player), 100), To Nearest), 100)), 3);
        If(Compare(Divide(Round To Integer(Multiply(Horizontal Facing Angle Of(Event Player), 100), To Nearest), 100), ==, 30));
            Start Forcing Player To Be Hero(Event Player, Hero(Bastion));
        Else If(Compare(Divide(Round To Integer(Multiply(Horizontal Facing Angle Of(Event Player), 100), To Nearest), 100), ==, 60));
            Start Forcing Player To Be Hero(Event Player, Hero(Reinhardt));
        Else If(Compare(Divide(Round To Integer(Multiply(Horizontal Facing Angle Of(Event Player), 100), To Nearest), 100), ==, 90));
            Start Forcing Player To Be Hero(Event Player, Hero(Ana));
        Else;
            Small Message(Event Player, Custom String("Could not detect interact button, or button not 'F', 'U' or 'O'"));
        End;
        Stop Facing(Event Player);
        Stop Forcing Player To Be Hero(Event Player);
        Set Facing(Event Player, (Event Player).oldFacing, To World);
    }
}

